import React, { useState } from 'react';
import GridLayout from 'react-grid-layout';
import 'react-grid-layout/css/styles.css';
import 'react-resizable/css/styles.css';
import { useDispatch, useSelector } from 'react-redux';
import { actions } from '../store';
import CardEditor from './CardEditor';

const CARD_ICONS = { bar: '📊', line: '📈', pie: '🥧', scalar: '🔢', table: '📋', map: '🗺️', area: '📉', row: '📊' };

export default function DashboardCanvas({ activeTab }) {
  const dispatch = useDispatch();
  const cards = useSelector(s => s.builder.config.cards).filter(
    c => activeTab === null ? c.tabIndex === undefined : c.tabIndex === activeTab
  );
  const [editingCard, setEditingCard] = useState(null);

  const layout = cards.map(c => ({ i: c.id, x: c.col, y: c.row, w: c.sizeX, h: c.sizeY }));

  const onLayoutChange = (newLayout) => {
    dispatch(actions.updateCardLayout(
      newLayout.map(l => ({ id: l.i, col: l.x, row: l.y, sizeX: l.w, sizeY: l.h }))
    ));
  };

  const onDrop = (layout, item, e) => {
    const cardType = e.dataTransfer.getData('cardType');
    if (!cardType) return;
    dispatch(actions.addCard({
      type: cardType,
      title: cardType.charAt(0).toUpperCase() + cardType.slice(1) + ' Chart',
      col: item.x, row: item.y, sizeX: item.w, sizeY: item.h,
      tabIndex: activeTab ?? undefined,
    }));
  };

  return (
    <div
      style={styles.canvas}
      onDragOver={e => e.preventDefault()}
    >
      {cards.length === 0 && (
        <div style={styles.empty}>
          <p>Drag cards from the left panel or click a card type to add</p>
        </div>
      )}
      <GridLayout
        className="layout"
        layout={layout}
        cols={24}
        rowHeight={60}
        width={1100}
        onLayoutChange={onLayoutChange}
        isDroppable
        onDrop={onDrop}
        droppingItem={{ i: '__dropping__', w: 6, h: 4 }}
      >
        {cards.map(card => (
          <div key={card.id} style={styles.card}>
            <div style={styles.cardHeader}>
              <span>{CARD_ICONS[card.type] || '📋'} {card.title}</span>
              <div style={{ display: 'flex', gap: 4 }}>
                <button style={styles.iconBtn} onClick={() => setEditingCard(card)} title="Edit">✏️</button>
                <button style={styles.iconBtn} onClick={() => dispatch(actions.removeCard(card.id))} title="Remove">🗑️</button>
              </div>
            </div>
            <div style={styles.cardBody}>
              {card.query
                ? <code style={styles.queryPreview}>{card.query.slice(0, 80)}{card.query.length > 80 ? '…' : ''}</code>
                : <span style={styles.noQuery}>No query — click ✏️ to edit</span>
              }
            </div>
          </div>
        ))}
      </GridLayout>

      {editingCard && (
        <CardEditor
          card={editingCard}
          onSave={updated => { dispatch(actions.updateCard(updated)); setEditingCard(null); }}
          onClose={() => setEditingCard(null)}
        />
      )}
    </div>
  );
}

const styles = {
  canvas: { flex: 1, background: '#f1f3f5', padding: 16, overflowY: 'auto', minHeight: 600 },
  empty: { display: 'flex', alignItems: 'center', justifyContent: 'center', height: 200, color: '#adb5bd', fontSize: 14 },
  card: { background: '#fff', border: '1px solid #dee2e6', borderRadius: 8, overflow: 'hidden', display: 'flex', flexDirection: 'column' },
  cardHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '6px 10px', background: '#f8f9fa', borderBottom: '1px solid #dee2e6', fontSize: 13, fontWeight: 600 },
  cardBody: { padding: 10, flex: 1, display: 'flex', alignItems: 'center' },
  queryPreview: { fontSize: 11, color: '#495057', background: '#f8f9fa', padding: '4px 6px', borderRadius: 4, wordBreak: 'break-all' },
  noQuery: { fontSize: 12, color: '#adb5bd', fontStyle: 'italic' },
  iconBtn: { background: 'none', border: 'none', cursor: 'pointer', fontSize: 14, padding: 2 },
};
